271→    const resolvedConfig = resolveExecutorConfig(agentExecutorConfig, collectionExecutorConfig);
272→
273→    // Parse collection-level env vars and merge with agent env vars
274→    // When callerEnvVars is provided, skip collection env vars entirely
275→    const collectionEnvVars = useCallerEnvVars ? {} : parseEnvVars(collection.envVars);
276→    const mergedEnvVars = mergeEnvVars(collectionEnvVars, agentEnvVars);
