  7→ *
  8→ * Route: /api/chat/[username]/[uid]/conversation/[conversationId]
  9→ * Uses username/uid instead of agent id for cleaner public URLs
 10→ */
 11→
 12→import { Prisma, prisma } from '@tpmjs/db';
 13→import type { AIProvider } from '@tpmjs/types/agent';
 14→import { SendMessageSchema } from '@tpmjs/types/agent';
 15→import type { LanguageModel, ModelMessage } from 'ai';
 16→import { type NextRequest, NextResponse } from 'next/server';
 17→import { decryptApiKey } from '@/lib/crypto/api-keys';
 18→import { logActivity } from '~/lib/activity';
 19→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
 20→
 21→/**
 22→ * Rate limit for chat messages: 30 requests per minute
 23→ * This is stricter than default because chat involves expensive LLM calls
 24→ */
 25→const CHAT_RATE_LIMIT: RateLimitConfig = {
 26→  limit: 30,
 27→  windowSeconds: 60,
 28→};
 29→
 30→export const runtime = 'nodejs';
 31→export const dynamic = 'force-dynamic';
 32→export const maxDuration = 300; // 5 minutes for long agentic runs
 33→
 34→type RouteContext = {
 35→  params: Promise<{ username: string; uid: string; conversationId: string }>;
 36→};
 37→
 38→/**
 39→ * Find agent by username and uid
 40→ */
 41→async function findAgentByUsernameAndUid(username: string, uid: string) {
 42→  return prisma.agent.findFirst({
 43→    where: {
 44→      uid,
 45→      user: { username },
 46→    },
 47→    select: { id: true },
 48→  });
 49→}
 50→
 51→/**
 52→ * Get AI provider SDK based on provider type
 53→ */
 54→async function getProviderModel(
 55→  provider: AIProvider,
 56→  modelId: string,
 57→  apiKey: string
 58→): Promise<LanguageModel> {
 59→  switch (provider) {
 60→    case 'OPENAI': {
 61→      const { createOpenAI } = await import('@ai-sdk/openai');
 62→      return createOpenAI({ apiKey })(modelId);
 63→    }
 64→    case 'ANTHROPIC': {
 65→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 66→      return createAnthropic({ apiKey })(modelId);
 67→    }
 68→    case 'GOOGLE': {
 69→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 70→      return createGoogleGenerativeAI({ apiKey })(modelId);
 71→    }
 72→    case 'GROQ': {
 73→      const { createGroq } = await import('@ai-sdk/groq');
 74→      return createGroq({ apiKey })(modelId);
 75→    }
 76→    case 'MISTRAL': {
 77→      const { createMistral } = await import('@ai-sdk/mistral');
 78→      return createMistral({ apiKey })(modelId);
 79→    }
 80→    default:
 81→      throw new Error(`Unsupported provider: ${provider}`);
 82→  }
 83→}
 84→
 85→/**
 86→ * POST /api/chat/[username]/[uid]/conversation/[conversationId]
 87→ * Send a message and stream the AI response via SSE
 88→ */
 89→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: large streaming chat handler with auth, validation, and SSE logic
 90→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 91→  // Check rate limit first to prevent expensive LLM calls
 92→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
 93→  if (rateLimitResponse) {
 94→    return rateLimitResponse;
 95→  }
 96→
 97→  const { username, uid, conversationId } = await context.params;
 98→
 99→  try {
100→    const body = await request.json();
101→    const parsed = SendMessageSchema.safeParse(body);
102→    if (!parsed.success) {
103→      return NextResponse.json(
104→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
105→        { status: 400 }
106→      );
107→    }
108→
109→    // Fetch agent with all tool relations using username + uid
110→    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
111→      '@/lib/agents/build-tools'
112→    );
113→    const agent = await fetchAgentByUsernameAndUidWithTools(username, uid);
114→
115→    if (!agent) {
116→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
117→    }
118→
119→    // Map provider to expected key name format
120→    const providerKeyNames: Record<string, string> = {
121→      OPENAI: 'OPENAI_API_KEY',
122→      ANTHROPIC: 'ANTHROPIC_API_KEY',
123→      GOOGLE: 'GOOGLE_API_KEY',
124→      GROQ: 'GROQ_API_KEY',
125→      MISTRAL: 'MISTRAL_API_KEY',
126→    };
127→    const keyName = providerKeyNames[agent.provider];
128→
129→    if (!keyName) {
130→      return NextResponse.json(
131→        { success: false, error: `Unsupported provider: ${agent.provider}` },
132→        { status: 400 }
133→      );
134→    }
135→
136→    // Get user's API key for this provider
137→    const userApiKey = await prisma.userApiKey.findUnique({
138→      where: {
139→        userId_keyName: {
140→          userId: agent.userId,
141→          keyName,
142→        },
143→      },
144→    });
145→
146→    if (!userApiKey) {
147→      return NextResponse.json(
148→        {
149→          success: false,
150→          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
151→        },
152→        { status: 400 }
153→      );
154→    }
155→
156→    // Decrypt the API key
157→    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
158→
159→    // Get or create conversation
160→    let conversation = await prisma.conversation.findUnique({
161→      where: {
162→        agentId_slug: {
163→          agentId: agent.id,
164→          slug: conversationId,
165→        },
166→      },
167→    });
168→
169→    if (!conversation) {
170→      conversation = await prisma.conversation.create({
171→        data: {
172→          agentId: agent.id,
173→          slug: conversationId,
174→          title: parsed.data.message.slice(0, 100),
175→        },
176→      });
177→
178→      // Log activity for new conversation (fire-and-forget)
179→      if (agent.userId) {
180→        logActivity({
181→          userId: agent.userId,
182→          type: 'AGENT_CONVERSATION_STARTED',
183→          targetName: agent.name,
184→          targetType: 'agent',
185→          agentId: agent.id,
186→        });
187→      }
188→    }
189→
190→    // Fetch recent messages for context
191→    const recentMessages = await prisma.message.findMany({
192→      where: { conversationId: conversation.id },
193→      orderBy: { createdAt: 'desc' },
194→      take: agent.maxMessagesInContext,
195→    });
196→
197→    // Reverse to get chronological order
198→    recentMessages.reverse();
199→
200→    // Save user message
201→    await prisma.message.create({
202→      data: {
203→        conversationId: conversation.id,
204→        role: 'USER',
205→        content: parsed.data.message,
206→      },
207→    });
208→
209→    // Build AI SDK messages from conversation history
210→    const { streamText, stepCountIs } = await import('ai');
211→
212→    const messages: ModelMessage[] = [];
213→
214→    // Add system prompt if defined
215→    if (agent.systemPrompt) {
216→      messages.push({
217→        role: 'system',
218→        content: agent.systemPrompt,
219→      });
220→    }
221→
222→    // Build a set of tool call IDs that have corresponding tool results
223→    // This is needed because AI SDK requires every tool call to have a matching tool result
224→    const toolResultIds = new Set(
225→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
226→    );
227→
228→    // Add conversation history - properly format for AI SDK
229→    for (const msg of recentMessages) {
230→      if (msg.role === 'USER') {
231→        messages.push({ role: 'user', content: msg.content });
232→      } else if (msg.role === 'ASSISTANT') {
233→        // For assistant messages with tool calls, include ToolCallParts in content
234→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
235→          // Only include tool calls that have matching tool results
236→          // AI SDK fails if there's a tool call without a corresponding tool result
237→          const validToolCalls = (
238→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
239→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
240→
241→          if (validToolCalls.length > 0) {
242→            const toolCallParts = validToolCalls.map((tc) => ({
243→              type: 'tool-call' as const,
244→              toolCallId: tc.toolCallId,
245→              toolName: tc.toolName,
246→              input: tc.args,
247→            }));
248→            // Content includes text (if any) plus tool call parts
249→            const content: Array<
250→              | { type: 'text'; text: string }
251→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
252→            > = [];
253→            if (msg.content) {
254→              content.push({ type: 'text', text: msg.content });
255→            }
256→            content.push(...toolCallParts);
257→            messages.push({
258→              role: 'assistant',
259→              content,
260→            });
261→          } else {
262→            // All tool calls are missing results, just include text content
263→            messages.push({
264→              role: 'assistant',
265→              content: msg.content || '',
266→            });
267→          }
268→        } else {
269→          messages.push({
270→            role: 'assistant',
271→            content: msg.content,
272→          });
273→        }
274→      } else if (msg.role === 'TOOL') {
275→        // Tool results use the 'tool' role with content array
276→        messages.push({
277→          role: 'tool',
278→          content: [
279→            {
280→              type: 'tool-result' as const,
281→              toolCallId: msg.toolCallId || '',
282→              toolName: msg.toolName || '',
283→              output: {
284→                type: 'json' as const,
285→                value: msg.toolResult,
286→              },
287→            },
288→          ],
289→        });
290→      }
291→    }
292→
293→    // Add new user message
294→    messages.push({ role: 'user', content: parsed.data.message });
295→
296→    // Build tools from agent configuration
297→    const tools = buildAgentTools(agent);
298→
299→    // Get the provider model
300→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
301→
302→    // Create SSE stream
303→    const stream = new ReadableStream({
304→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: SSE streaming with tool calls and error handling
305→      async start(controller) {
306→        const encoder = new TextEncoder();
307→
308→        const sendEvent = (event: string, data: unknown) => {
309→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
310→          controller.enqueue(encoder.encode(message));
311→        };
312→
313→        try {
314→          const startTime = Date.now();
315→          let fullContent = '';
316→          // Accumulate tool calls with their input args
317→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
318→            new Map();
319→          // Collect tool results to save AFTER assistant message (for correct chronological order)
320→          const pendingToolResults: Array<{
321→            toolCallId: string;
322→            toolName: string;
323→            output: unknown;
324→          }> = [];
325→          let inputTokens = 0;
326→          let outputTokens = 0;
327→
328→          // Stream the response with agentic loop control
329→          const result = await streamText({
330→            model,
331→            messages,
332→            tools,
333→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
334→            onChunk: async ({ chunk }) => {
335→              // Stream tool calls as they come in and capture their inputs
336→              if (chunk.type === 'tool-call') {
337→                const input = 'args' in chunk ? chunk.args : chunk.input;
338→                // Store tool call with input for later persistence
339→                toolCallsMap.set(chunk.toolCallId, {
340→                  toolCallId: chunk.toolCallId,
341→                  toolName: chunk.toolName,
342→                  args: input,
343→                });
344→                sendEvent('tool_call', {
345→                  toolCallId: chunk.toolCallId,
346→                  toolName: chunk.toolName,
347→                  input,
348→                });
349→              }
350→            },
351→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: step finish handler with tool call tracking and usage aggregation
352→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
353→              // Capture tool calls from step finish (backup in case onChunk missed any)
354→              if (toolCalls && Array.isArray(toolCalls)) {
355→                for (const tc of toolCalls) {
356→                  if (!toolCallsMap.has(tc.toolCallId)) {
357→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
358→                    const args =
359→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
360→                    toolCallsMap.set(tc.toolCallId, {
361→                      toolCallId: tc.toolCallId,
362→                      toolName: tc.toolName,
363→                      args,
364→                    });
365→                  }
366→                }
367→              }
368→
369→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
370→              if (toolResults && toolResults.length > 0) {
371→                for (const tr of toolResults) {
372→                  sendEvent('tool_result', {
373→                    toolCallId: tr.toolCallId,
374→                    output: tr.output,
375→                  });
376→
377→                  // Collect tool results to save after assistant message
378→                  pendingToolResults.push({
379→                    toolCallId: tr.toolCallId,
380→                    toolName: tr.toolName,
381→                    output: tr.output,
382→                  });
383→                }
384→              }
385→
386→              // Track token usage
387→              if (usage) {
388→                inputTokens += usage.inputTokens ?? 0;
389→                outputTokens += usage.outputTokens ?? 0;
390→              }
391→            },
392→          });
393→
394→          // Stream text chunks
395→          for await (const chunk of result.textStream) {
396→            fullContent += chunk;
397→            sendEvent('chunk', { type: 'text', text: chunk });
398→          }
399→
400→          // Get final response data
401→          const finalUsage = await result.usage;
402→
403→          // Convert tool calls map to array for storage
404→          const allToolCalls = Array.from(toolCallsMap.values());
405→
406→          // Update token counts from final usage
407→          if (finalUsage) {
408→            inputTokens = finalUsage.inputTokens ?? inputTokens;
409→            outputTokens = finalUsage.outputTokens ?? outputTokens;
410→          }
411→
412→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
413→          const assistantMessage = await prisma.message.create({
414→            data: {
415→              conversationId: conversation.id,
416→              role: 'ASSISTANT',
417→              content: fullContent,
418→              // Cast to Prisma-compatible JSON type
419→              toolCalls:
420→                allToolCalls.length > 0
421→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
422→                  : Prisma.JsonNull,
423→              inputTokens,
424→              outputTokens,
425→            },
426→          });
427→
428→          // Now save TOOL messages (after assistant, for correct chronological order)
429→          for (const tr of pendingToolResults) {
430→            await prisma.message.create({
431→              data: {
432→                conversationId: conversation.id,
433→                role: 'TOOL',
434→                content: JSON.stringify(tr.output),
435→                toolCallId: tr.toolCallId,
436→                toolName: tr.toolName,
437→                toolResult: tr.output as object,
438→              },
439→            });
440→          }
441→
442→          // Update conversation timestamp
443→          await prisma.conversation.update({
444→            where: { id: conversation.id },
445→            data: { updatedAt: new Date() },
446→          });
447→
448→          const executionTimeMs = Date.now() - startTime;
449→
450→          // Send token usage
451→          sendEvent('tokens', {
452→            inputTokens,
453→            outputTokens,
454→            totalTokens: inputTokens + outputTokens,
455→          });
456→
457→          // Send completion event
458→          sendEvent('complete', {
459→            messageId: assistantMessage.id,
460→            conversationId: conversation.id,
461→            executionTimeMs,
462→          });
463→        } catch (error) {
464→          console.error('Agent conversation error:', error);
465→          sendEvent('error', {
466→            message: error instanceof Error ? error.message : 'Unknown error',
467→          });
468→        } finally {
469→          controller.close();
470→        }
471→      },
472→    });
473→
474→    return new NextResponse(stream, {
475→      headers: {
476→        'Content-Type': 'text/event-stream',
477→        'Cache-Control': 'no-cache',
478→        Connection: 'keep-alive',
479→      },
480→    });
481→  } catch (error) {
482→    console.error('Failed to process message:', error);
483→    return NextResponse.json(
484→      {
485→        success: false,
486→        error: error instanceof Error ? error.message : 'Failed to process message',
487→      },
488→      { status: 500 }
489→    );
490→  }
491→}
