610→/**
611→ * DELETE /api/chat/[username]/[uid]/conversation/[conversationId]
612→ * Delete a conversation
613→ */
614→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
615→  const { username, uid, conversationId } = await context.params;
616→
617→  try {
618→    // Fetch agent by username and uid
