 77→/**
 78→ * POST /api/agents/[id]/conversation/[conversationId]
 79→ * Send a message and stream the AI response via SSE
 80→ */
 81→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
 82→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 83→  const startTime = Date.now();
 84→
 85→  // Authenticate request (supports both session and API key)
 86→  const authResult = await authenticateRequest();
 87→
 88→  if (!authResult.authenticated) {
 89→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 90→  }
 91→
 92→  // Check scope for API key auth
 93→  if (authResult.authenticated && !authResult.isSessionAuth) {
 94→    if (!hasScope(authResult, 'agent:chat')) {
 95→      return NextResponse.json(
 96→        { error: 'API key does not have agent:chat scope' },
 97→        { status: 403 }
 98→      );
 99→    }
100→  }
101→
102→  // Check rate limit (after auth so we can track by user if needed)
103→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
104→  if (rateLimitResponse) {
105→    return rateLimitResponse;
106→  }
107→
108→  const { id: agentId, conversationId } = await context.params;
109→
110→  try {
111→    const body = await request.json();
112→    const parsed = SendMessageSchema.safeParse(body);
113→    if (!parsed.success) {
114→      return NextResponse.json(
115→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
116→        { status: 400 }
117→      );
118→    }
119→
120→    // Fetch agent with all tool relations using agent ID
121→    const { fetchAgentWithTools, buildAgentTools } = await import('@/lib/agents/build-tools');
122→    const { getRequiredEnvVarsForAgent, getMissingEnvVars } = await import(
123→      '@/lib/agents/env-helpers'
124→    );
125→    const agent = await fetchAgentWithTools(agentId);
126→
127→    if (!agent) {
128→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
129→    }
130→
131→    // Check ownership
132→    const isOwner = authResult.userId === agent.userId;
133→
134→    // Non-owners can only access PUBLIC agents
135→    if (!isOwner && !agent.isPublic) {
136→      // Don't reveal that the agent exists - return 404
137→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
138→    }
139→
140→    // Map provider to expected key name format
141→    const providerKeyNames: Record<string, string> = {
142→      OPENAI: 'OPENAI_API_KEY',
143→      ANTHROPIC: 'ANTHROPIC_API_KEY',
144→      GOOGLE: 'GOOGLE_API_KEY',
145→      GROQ: 'GROQ_API_KEY',
146→      MISTRAL: 'MISTRAL_API_KEY',
147→    };
148→    const keyName = providerKeyNames[agent.provider];
149→
150→    if (!keyName) {
151→      return NextResponse.json(
152→        { success: false, error: `Unsupported provider: ${agent.provider}` },
153→        { status: 400 }
154→      );
155→    }
156→
157→    let apiKey: string;
158→    let callerEnvVars: Record<string, string> | undefined;
159→
160→    if (isOwner) {
161→      // Owner: use stored encrypted keys
162→      const userApiKey = await prisma.userApiKey.findUnique({
163→        where: {
164→          userId_keyName: {
165→            userId: agent.userId,
166→            keyName,
167→          },
168→        },
169→      });
170→
171→      if (!userApiKey) {
172→        return NextResponse.json(
173→          {
174→            success: false,
175→            error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→          },
177→          { status: 400 }
178→        );
179→      }
180→
181→      // Decrypt the API key
182→      apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→      // callerEnvVars stays undefined - buildAgentTools will use agent's stored env vars
184→    } else {
185→      // Non-owner accessing public agent: must provide their own credentials
186→      if (!parsed.data.providerApiKey) {
187→        return NextResponse.json(
188→          {
189→            success: false,
190→            error: 'Public agent access requires your own API key',
191→            details: {
192→              code: 'MISSING_PROVIDER_KEY',
193→              requiredProvider: agent.provider,
194→              hint: `Provide your ${agent.provider} API key in the 'providerApiKey' field`,
195→            },
196→          },
197→          { status: 400 }
198→        );
199→      }
200→
201→      apiKey = parsed.data.providerApiKey;
202→      callerEnvVars = parsed.data.env || {};
203→
204→      // Check for required environment variables
205→      const requiredEnvVars = getRequiredEnvVarsForAgent(agent);
206→      const missingEnvVars = getMissingEnvVars(requiredEnvVars, callerEnvVars);
207→
208→      if (missingEnvVars.length > 0) {
209→        return NextResponse.json(
210→          {
211→            success: false,
212→            error: 'Missing required environment variables',
213→            details: {
214→              code: 'MISSING_ENV_VARS',
215→              missingVars: missingEnvVars.map((e) => ({
216→                name: e.name,
217→                description: e.description,
218→              })),
219→              hint: "Provide these variables in the 'env' field of your request",
220→            },
221→          },
222→          { status: 400 }
223→        );
224→      }
225→    }
226→
227→    // Get or create conversation
228→    let conversation = await prisma.conversation.findUnique({
229→      where: {
230→        agentId_slug: {
231→          agentId: agent.id,
232→          slug: conversationId,
233→        },
234→      },
235→    });
236→
237→    if (!conversation) {
238→      conversation = await prisma.conversation.create({
239→        data: {
240→          agentId: agent.id,
241→          slug: conversationId,
242→          title: parsed.data.message.slice(0, 100),
243→        },
244→      });
245→
246→      // Log activity for new conversation (fire-and-forget)
247→      if (agent.userId) {
248→        logActivity({
249→          userId: agent.userId,
250→          type: 'AGENT_CONVERSATION_STARTED',
251→          targetName: agent.name,
252→          targetType: 'agent',
253→          agentId: agent.id,
254→        });
255→      }
256→    }
257→
258→    // Fetch recent messages for context
259→    const recentMessages = await prisma.message.findMany({
260→      where: { conversationId: conversation.id },
261→      orderBy: { createdAt: 'desc' },
262→      take: agent.maxMessagesInContext,
263→    });
264→
265→    // Reverse to get chronological order
266→    recentMessages.reverse();
267→
268→    // Save user message
269→    await prisma.message.create({
270→      data: {
271→        conversationId: conversation.id,
272→        role: 'USER',
273→        content: parsed.data.message,
274→      },
275→    });
276→
277→    // Build AI SDK messages from conversation history
278→    const { streamText, stepCountIs } = await import('ai');
279→
280→    const messages: ModelMessage[] = [];
281→
282→    // Add system prompt if defined
283→    if (agent.systemPrompt) {
284→      messages.push({
285→        role: 'system',
286→        content: agent.systemPrompt,
287→      });
288→    }
289→
290→    // Build a set of tool call IDs that have corresponding tool results
291→    // This is needed because AI SDK requires every tool call to have a matching tool result
292→    const toolResultIds = new Set(
293→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
294→    );
295→
296→    // Add conversation history - properly format for AI SDK
297→    for (const msg of recentMessages) {
298→      if (msg.role === 'USER') {
299→        messages.push({ role: 'user', content: msg.content });
300→      } else if (msg.role === 'ASSISTANT') {
301→        // For assistant messages with tool calls, include ToolCallParts in content
302→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
303→          // Only include tool calls that have matching tool results
304→          // AI SDK fails if there's a tool call without a corresponding tool result
305→          const validToolCalls = (
306→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
307→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
308→
309→          if (validToolCalls.length > 0) {
310→            const toolCallParts = validToolCalls.map((tc) => ({
311→              type: 'tool-call' as const,
312→              toolCallId: tc.toolCallId,
313→              toolName: tc.toolName,
314→              input: tc.args,
315→            }));
316→            // Content includes text (if any) plus tool call parts
317→            const content: Array<
318→              | { type: 'text'; text: string }
319→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
320→            > = [];
321→            if (msg.content) {
322→              content.push({ type: 'text', text: msg.content });
323→            }
324→            content.push(...toolCallParts);
325→            messages.push({
326→              role: 'assistant',
327→              content,
328→            });
329→          } else {
330→            // All tool calls are missing results, just include text content
331→            messages.push({
332→              role: 'assistant',
333→              content: msg.content || '',
334→            });
335→          }
336→        } else {
337→          messages.push({
338→            role: 'assistant',
339→            content: msg.content,
340→          });
341→        }
342→      } else if (msg.role === 'TOOL') {
343→        // Tool results use the 'tool' role with content array
344→        messages.push({
345→          role: 'tool',
346→          content: [
347→            {
348→              type: 'tool-result' as const,
349→              toolCallId: msg.toolCallId || '',
350→              toolName: msg.toolName || '',
351→              output: {
352→                type: 'json' as const,
353→                value: msg.toolResult,
354→              },
355→            },
356→          ],
357→        });
358→      }
359→    }
360→
361→    // Add new user message
362→    messages.push({ role: 'user', content: parsed.data.message });
363→
364→    // Build tools from agent configuration
365→    // Build tools - pass callerEnvVars if non-owner accessing public agent
366→    const tools = buildAgentTools(agent, callerEnvVars);
367→
368→    // Get the provider model
369→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
370→
371→    // Create SSE stream
372→    const stream = new ReadableStream({
373→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
374→      async start(controller) {
375→        const encoder = new TextEncoder();
376→
377→        const sendEvent = (event: string, data: unknown) => {
378→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
379→          controller.enqueue(encoder.encode(message));
380→        };
381→
382→        try {
383→          const startTime = Date.now();
384→          let fullContent = '';
385→          // Accumulate tool calls with their input args
386→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
387→            new Map();
388→          // Collect tool results to save AFTER assistant message (for correct chronological order)
389→          const pendingToolResults: Array<{
390→            toolCallId: string;
391→            toolName: string;
392→            output: unknown;
393→          }> = [];
394→          let inputTokens = 0;
395→          let outputTokens = 0;
396→
397→          // Stream the response with agentic loop control
398→          const result = await streamText({
399→            model,
400→            messages,
401→            tools,
402→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
403→            onChunk: async ({ chunk }) => {
404→              // Stream tool calls as they come in and capture their inputs
405→              if (chunk.type === 'tool-call') {
406→                const input = 'args' in chunk ? chunk.args : chunk.input;
407→
408→                // Log tool call for debugging
409→                console.log('[Agent] Tool call initiated:', {
410→                  toolName: chunk.toolName,
411→                  toolCallId: chunk.toolCallId,
412→                  input: JSON.stringify(input).slice(0, 500),
413→                });
414→
415→                // Store tool call with input for later persistence
416→                toolCallsMap.set(chunk.toolCallId, {
417→                  toolCallId: chunk.toolCallId,
418→                  toolName: chunk.toolName,
419→                  args: input,
420→                });
421→                sendEvent('tool_call', {
422→                  toolCallId: chunk.toolCallId,
423→                  toolName: chunk.toolName,
424→                  input,
425→                });
426→              }
427→            },
428→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
429→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
430→              // Capture tool calls from step finish (backup in case onChunk missed any)
431→              if (toolCalls && Array.isArray(toolCalls)) {
432→                for (const tc of toolCalls) {
433→                  if (!toolCallsMap.has(tc.toolCallId)) {
434→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
435→                    const args =
436→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
437→                    toolCallsMap.set(tc.toolCallId, {
438→                      toolCallId: tc.toolCallId,
439→                      toolName: tc.toolName,
440→                      args,
441→                    });
442→                  }
443→                }
444→              }
445→
446→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
447→              if (toolResults && toolResults.length > 0) {
448→                for (const tr of toolResults) {
449→                  // Check if this is an error result (AI SDK wraps errors in the output)
450→                  const isError =
451→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
452→
453→                  // Log tool results for debugging
454→                  if (isError) {
455→                    console.error('[Agent] Tool execution failed:', {
456→                      toolName: tr.toolName,
457→                      toolCallId: tr.toolCallId,
458→                      error: tr.output,
459→                    });
460→                  } else {
461→                    console.log('[Agent] Tool execution success:', {
462→                      toolName: tr.toolName,
463→                      toolCallId: tr.toolCallId,
464→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
465→                    });
466→                  }
467→
468→                  sendEvent('tool_result', {
469→                    toolCallId: tr.toolCallId,
470→                    output: tr.output,
471→                    isError,
472→                  });
473→
474→                  // Collect tool results to save after assistant message
475→                  pendingToolResults.push({
476→                    toolCallId: tr.toolCallId,
477→                    toolName: tr.toolName,
478→                    output: tr.output,
479→                  });
480→
481→                  // Track each tool call execution event
482→                  trackExecution({
483→                    eventType: 'tool_call',
484→                    source: 'agent_chat',
485→                    userId: authResult.userId ?? undefined,
486→                    apiKeyId: authResult.apiKeyId ?? undefined,
487→                    agentId: agent.id,
488→                    toolName: tr.toolName,
489→                    status: isError ? 'error' : 'success',
490→                  });
491→                }
492→              }
493→
494→              // Track token usage
495→              if (usage) {
496→                inputTokens += usage.inputTokens ?? 0;
497→                outputTokens += usage.outputTokens ?? 0;
498→              }
499→            },
500→          });
501→
502→          // Stream text chunks
503→          for await (const chunk of result.textStream) {
504→            fullContent += chunk;
505→            sendEvent('chunk', { type: 'text', text: chunk });
506→          }
507→
508→          // Get final response data
509→          const finalUsage = await result.usage;
510→
511→          // Convert tool calls map to array for storage
512→          const allToolCalls = Array.from(toolCallsMap.values());
513→
514→          // Update token counts from final usage
515→          if (finalUsage) {
516→            inputTokens = finalUsage.inputTokens ?? inputTokens;
517→            outputTokens = finalUsage.outputTokens ?? outputTokens;
518→          }
519→
520→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
521→          const assistantMessage = await prisma.message.create({
522→            data: {
523→              conversationId: conversation.id,
524→              role: 'ASSISTANT',
525→              content: fullContent,
526→              // Cast to Prisma-compatible JSON type
527→              toolCalls:
528→                allToolCalls.length > 0
529→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
530→                  : Prisma.JsonNull,
531→              inputTokens,
532→              outputTokens,
533→            },
534→          });
535→
536→          // Now save TOOL messages (after assistant, for correct chronological order)
537→          for (const tr of pendingToolResults) {
538→            await prisma.message.create({
539→              data: {
540→                conversationId: conversation.id,
541→                role: 'TOOL',
542→                content: JSON.stringify(tr.output),
543→                toolCallId: tr.toolCallId,
544→                toolName: tr.toolName,
545→                toolResult: tr.output as object,
546→              },
547→            });
548→          }
549→
550→          // Update conversation timestamp
551→          await prisma.conversation.update({
552→            where: { id: conversation.id },
553→            data: { updatedAt: new Date() },
554→          });
555→
556→          const executionTimeMs = Date.now() - startTime;
557→
558→          // Send token usage
559→          sendEvent('tokens', {
560→            inputTokens,
561→            outputTokens,
562→            totalTokens: inputTokens + outputTokens,
563→          });
564→
565→          // Send completion event
566→          sendEvent('complete', {
567→            messageId: assistantMessage.id,
568→            conversationId: conversation.id,
569→            executionTimeMs,
570→          });
571→
572→          // Track agent run execution event
573→          trackExecution({
574→            eventType: 'agent_run',
575→            source: 'agent_chat',
576→            userId: authResult.userId ?? undefined,
577→            apiKeyId: authResult.apiKeyId ?? undefined,
578→            agentId: agent.id,
579→            status: 'success',
580→            durationMs: executionTimeMs,
581→            tokensIn: inputTokens,
582→            tokensOut: outputTokens,
583→          });
584→
585→          // Track usage
586→          if (authResult.userId) {
587→            trackUsage({
588→              apiKeyId: authResult.apiKeyId ?? undefined,
589→              userId: authResult.userId,
590→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
591→              method: 'POST',
592→              statusCode: 200,
593→              latencyMs: executionTimeMs,
594→              resourceType: 'agent',
595→              resourceId: agentId,
596→              tokensIn: inputTokens,
597→              tokensOut: outputTokens,
598→              model: agent.modelId,
599→            });
600→          }
601→        } catch (error) {
602→          // Log detailed error for debugging
603→          console.error('[Agent] Conversation stream error:', {
604→            error: error instanceof Error ? error.message : String(error),
605→            stack: error instanceof Error ? error.stack : undefined,
606→            agentId: agent.id,
607→            conversationId: conversation.id,
608→          });
609→          sendEvent('error', {
610→            message: error instanceof Error ? error.message : 'Unknown error',
611→          });
612→
613→          // Track agent run error
614→          trackExecution({
615→            eventType: 'agent_run',
616→            source: 'agent_chat',
617→            userId: authResult.userId ?? undefined,
618→            apiKeyId: authResult.apiKeyId ?? undefined,
619→            agentId: agent.id,
620→            status: 'error',
621→            durationMs: Date.now() - startTime,
622→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
623→          });
624→
625→          // Track error
626→          if (authResult.userId) {
627→            trackUsage({
628→              apiKeyId: authResult.apiKeyId ?? undefined,
629→              userId: authResult.userId,
630→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
631→              method: 'POST',
632→              statusCode: 500,
633→              latencyMs: Date.now() - startTime,
634→              resourceType: 'agent',
635→              resourceId: agentId,
636→              errorCode: 'STREAM_ERROR',
637→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
638→            });
639→          }
640→        } finally {
641→          controller.close();
642→        }
643→      },
644→    });
645→
646→    return new NextResponse(stream, {
647→      headers: {
648→        'Content-Type': 'text/event-stream',
649→        'Cache-Control': 'no-cache',
650→        Connection: 'keep-alive',
651→      },
652→    });
653→  } catch (error) {
654→    console.error('Failed to process message:', error);
655→    return NextResponse.json(
656→      {
657→        success: false,
658→        error: error instanceof Error ? error.message : 'Failed to process message',
659→      },
660→      { status: 500 }
661→    );
662→  }
663→}
