665→/**
666→ * GET /api/agents/[id]/conversation/[conversationId]
667→ * Retrieve conversation history with pagination
668→ *
669→ * Query params:
670→ * - limit: Max messages to return (default: 50, max: 100)
671→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
672→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
673→ * - format: 'json' for full debug view (no pagination, includes agent info)
674→ *
675→ * Default behavior (no before/after): Returns the most recent messages
676→ * With before: Returns messages older than the timestamp (for scrolling up)
677→ * With after: Returns messages newer than the timestamp (for refreshing)
678→ */
679→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
680→  const { id: agentId, conversationId } = await context.params;
681→  const { searchParams } = new URL(request.url);
682→
683→  const format = searchParams.get('format');
684→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
685→  const before = searchParams.get('before');
686→  const after = searchParams.get('after');
687→
688→  try {
689→    // Fetch agent by ID with more details for JSON format
690→    const agent = await prisma.agent.findUnique({
691→      where: { id: agentId },
692→      select: {
693→        id: true,
694→        uid: true,
695→        name: true,
696→        provider: true,
697→        modelId: true,
698→        executorType: true,
699→        executorConfig: true,
700→      },
701→    });
702→
703→    if (!agent) {
704→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
705→    }
706→
707→    // Fetch conversation
708→    const conversation = await prisma.conversation.findUnique({
709→      where: {
710→        agentId_slug: {
711→          agentId: agent.id,
712→          slug: conversationId,
713→        },
714→      },
715→    });
716→
717→    if (!conversation) {
718→      return NextResponse.json(
719→        { success: false, error: 'Conversation not found' },
720→        { status: 404 }
721→      );
722→    }
723→
724→    // For JSON format, return all messages with full details
725→    if (format === 'json') {
726→      const allMessages = await prisma.message.findMany({
727→        where: { conversationId: conversation.id },
728→        orderBy: { createdAt: 'asc' },
729→      });
730→
731→      const response = {
732→        _meta: {
733→          exportedAt: new Date().toISOString(),
734→          format: 'tpmjs-conversation-log',
735→          version: '1.0',
736→        },
737→        agent: {
738→          id: agent.id,
739→          uid: agent.uid,
740→          name: agent.name,
741→          provider: agent.provider,
742→          modelId: agent.modelId,
743→          executorType: agent.executorType,
744→          executorConfig: agent.executorConfig,
745→        },
746→        conversation: {
747→          id: conversation.id,
748→          slug: conversation.slug,
749→          title: conversation.title,
750→          createdAt: conversation.createdAt,
751→          updatedAt: conversation.updatedAt,
752→          messageCount: allMessages.length,
753→        },
754→        messages: allMessages.map((m) => ({
755→          id: m.id,
756→          role: m.role,
757→          content: m.content,
758→          toolCalls: m.toolCalls,
759→          toolCallId: m.toolCallId,
760→          toolName: m.toolName,
761→          toolResult: m.toolResult,
762→          inputTokens: m.inputTokens,
763→          outputTokens: m.outputTokens,
764→          createdAt: m.createdAt,
765→        })),
766→        stats: {
767→          totalMessages: allMessages.length,
768→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
769→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
770→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
771→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
772→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
773→        },
774→      };
775→
776→      // Return pretty-printed JSON with proper content type
777→      return new NextResponse(JSON.stringify(response, null, 2), {
778→        headers: {
779→          'Content-Type': 'application/json',
780→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
781→        },
782→      });
783→    }
784→
785→    // Standard paginated response
786→    const whereClause: {
787→      conversationId: string;
788→      createdAt?: { lt?: Date; gt?: Date };
789→    } = { conversationId: conversation.id };
790→
791→    if (before) {
792→      whereClause.createdAt = { lt: new Date(before) };
793→    } else if (after) {
794→      whereClause.createdAt = { gt: new Date(after) };
795→    }
796→
797→    // Determine fetch order:
798→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
799→    // - "after": Fetch asc (oldest first) to get messages after the cursor
800→    const shouldFetchDesc = !after;
801→
802→    // Fetch messages
803→    const messages = await prisma.message.findMany({
804→      where: whereClause,
805→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
806→      take: limit + 1,
807→    });
808→
809→    const hasMore = messages.length > limit;
810→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
811→
812→    // Reverse if we fetched in desc order to maintain chronological order
813→    if (shouldFetchDesc) {
814→      paginatedMessages = paginatedMessages.reverse();
815→    }
816→
817→    const mappedMessages = paginatedMessages.map((m) => ({
818→      id: m.id,
819→      role: m.role,
820→      content: m.content,
821→      toolCalls: m.toolCalls,
822→      toolCallId: m.toolCallId,
823→      toolName: m.toolName,
824→      toolResult: m.toolResult,
825→      inputTokens: m.inputTokens,
826→      outputTokens: m.outputTokens,
827→      createdAt: m.createdAt,
828→    }));
829→
830→    return NextResponse.json({
831→      success: true,
832→      data: {
833→        id: conversation.id,
834→        slug: conversation.slug,
835→        title: conversation.title,
836→        createdAt: conversation.createdAt,
837→        updatedAt: conversation.updatedAt,
838→        messages: mappedMessages,
839→      },
840→      pagination: {
841→        limit,
842→        hasMore,
843→        ...(before && { before }),
844→        ...(after && { after }),
845→      },
846→    });
847→  } catch (error) {
848→    console.error('Failed to fetch conversation:', error);
849→    return NextResponse.json(
850→      { success: false, error: 'Failed to fetch conversation' },
851→      { status: 500 }
852→    );
853→  }
854→}
