856→/**
857→ * DELETE /api/agents/[id]/conversation/[conversationId]
858→ * Delete a conversation
859→ */
860→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
861→  const { id: agentId, conversationId } = await context.params;
862→
863→  try {
864→    // Fetch agent by ID
865→    const agent = await prisma.agent.findUnique({
866→      where: { id: agentId },
867→      select: { id: true },
868→    });
869→
870→    if (!agent) {
871→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
872→    }
873→
874→    // Delete conversation (messages cascade)
875→    await prisma.conversation.deleteMany({
876→      where: {
877→        agentId: agent.id,
878→        slug: conversationId,
879→      },
880→    });
881→
882→    return NextResponse.json({
883→      success: true,
884→      data: { deleted: true },
885→    });
886→  } catch (error) {
887→    console.error('Failed to delete conversation:', error);
888→    return NextResponse.json(
889→      { success: false, error: 'Failed to delete conversation' },
890→      { status: 500 }
891→    );
892→  }
893→}
