805→/**
806→ * DELETE /api/[username]/agents/[agentSlug]/conversation/[conversationId]
807→ * Delete a conversation
808→ */
809→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
810→  const { username, agentSlug, conversationId } = await context.params;
811→
812→  try {
813→    // Fetch agent by username and slug
814→    const agent = await prisma.agent.findFirst({
815→      where: {
816→        uid: agentSlug,
817→        user: { username },
818→      },
819→      select: { id: true },
820→    });
821→
822→    if (!agent) {
823→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
824→    }
825→
826→    // Delete conversation (messages cascade)
827→    await prisma.conversation.deleteMany({
828→      where: {
829→        agentId: agent.id,
830→        slug: conversationId,
831→      },
832→    });
833→
834→    return NextResponse.json({
835→      success: true,
836→      data: { deleted: true },
837→    });
838→  } catch (error) {
839→    console.error('Failed to delete conversation:', error);
840→    return NextResponse.json(
841→      { success: false, error: 'Failed to delete conversation' },
842→      { status: 500 }
843→    );
844→  }
845→}
