 15→import { Prisma, prisma } from '@tpmjs/db';
 16→import type { AIProvider } from '@tpmjs/types/agent';
 17→import { SendMessageSchema } from '@tpmjs/types/agent';
 18→import type { LanguageModel, ModelMessage } from 'ai';
 19→import { type NextRequest, NextResponse } from 'next/server';
 20→import { decryptApiKey } from '@/lib/crypto/api-keys';
 21→import { logActivity } from '~/lib/activity';
 22→import { authenticateRequest, hasScope } from '~/lib/api-keys/middleware';
 23→import { trackUsage } from '~/lib/api-keys/usage';
 24→import { checkRateLimit, type RateLimitConfig } from '~/lib/rate-limit';
 25→import { trackExecution } from '~/lib/tracking/executions';
 26→
 27→/**
 28→ * Rate limit for chat messages: 30 requests per minute
 29→ * This is stricter than default because chat involves expensive LLM calls
 30→ */
 31→const CHAT_RATE_LIMIT: RateLimitConfig = {
 32→  limit: 30,
 33→  windowSeconds: 60,
 34→};
 35→
 36→export const runtime = 'nodejs';
 37→export const dynamic = 'force-dynamic';
 38→export const maxDuration = 300; // 5 minutes for long agentic runs
 39→
 40→type RouteContext = {
 41→  params: Promise<{ username: string; agentSlug: string; conversationId: string }>;
 42→};
 43→
 44→/**
 45→ * Get AI provider SDK based on provider type
 46→ */
 47→async function getProviderModel(
 48→  provider: AIProvider,
 49→  modelId: string,
 50→  apiKey: string
 51→): Promise<LanguageModel> {
 52→  switch (provider) {
 53→    case 'OPENAI': {
 54→      const { createOpenAI } = await import('@ai-sdk/openai');
 55→      return createOpenAI({ apiKey })(modelId);
 56→    }
 57→    case 'ANTHROPIC': {
 58→      const { createAnthropic } = await import('@ai-sdk/anthropic');
 59→      return createAnthropic({ apiKey })(modelId);
 60→    }
 61→    case 'GOOGLE': {
 62→      const { createGoogleGenerativeAI } = await import('@ai-sdk/google');
 63→      return createGoogleGenerativeAI({ apiKey })(modelId);
 64→    }
 65→    case 'GROQ': {
 66→      const { createGroq } = await import('@ai-sdk/groq');
 67→      return createGroq({ apiKey })(modelId);
 68→    }
 69→    case 'MISTRAL': {
 70→      const { createMistral } = await import('@ai-sdk/mistral');
 71→      return createMistral({ apiKey })(modelId);
 72→    }
 73→    default:
 74→      throw new Error(`Unsupported provider: ${provider}`);
 75→  }
 76→}
 77→
 78→/**
 79→ * POST /api/[username]/agents/[agentSlug]/conversation/[conversationId]
 80→ * Send a message and stream the AI response via SSE
 81→ */
 82→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic required
 83→export async function POST(request: NextRequest, context: RouteContext): Promise<Response> {
 84→  const startTime = Date.now();
 85→
 86→  // Authenticate request (supports both session and API key)
 87→  const authResult = await authenticateRequest();
 88→
 89→  if (!authResult.authenticated) {
 90→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
 91→  }
 92→
 93→  // Check scope for API key auth
 94→  if (authResult.authenticated && !authResult.isSessionAuth) {
 95→    if (!hasScope(authResult, 'agent:chat')) {
 96→      return NextResponse.json(
 97→        { error: 'API key does not have agent:chat scope' },
 98→        { status: 403 }
 99→      );
100→    }
101→  }
102→
103→  // Check rate limit (after auth so we can track by user if needed)
104→  const rateLimitResponse = checkRateLimit(request, CHAT_RATE_LIMIT);
105→  if (rateLimitResponse) {
106→    return rateLimitResponse;
107→  }
108→
109→  const { username, agentSlug, conversationId } = await context.params;
110→
111→  try {
112→    const body = await request.json();
113→    const parsed = SendMessageSchema.safeParse(body);
114→    if (!parsed.success) {
115→      return NextResponse.json(
116→        { success: false, error: 'Invalid request', details: parsed.error.flatten() },
117→        { status: 400 }
118→      );
119→    }
120→
121→    // Fetch agent by username and slug with all tool relations
122→    const { fetchAgentByUsernameAndUidWithTools, buildAgentTools } = await import(
123→      '@/lib/agents/build-tools'
124→    );
125→    const agent = await fetchAgentByUsernameAndUidWithTools(username, agentSlug);
126→
127→    if (!agent) {
128→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
129→    }
130→
131→    // Owner-only enforcement: Only the agent owner can chat with the agent
132→    if (authResult.userId !== agent.userId) {
133→      return NextResponse.json(
134→        {
135→          success: false,
136→          error:
137→            'Fork this agent to use it. Only the agent owner can chat with agents. ' +
138→            'Visit the agent page to fork it to your account.',
139→        },
140→        { status: 403 }
141→      );
142→    }
143→
144→    // Map provider to expected key name format
145→    const providerKeyNames: Record<string, string> = {
146→      OPENAI: 'OPENAI_API_KEY',
147→      ANTHROPIC: 'ANTHROPIC_API_KEY',
148→      GOOGLE: 'GOOGLE_API_KEY',
149→      GROQ: 'GROQ_API_KEY',
150→      MISTRAL: 'MISTRAL_API_KEY',
151→    };
152→    const keyName = providerKeyNames[agent.provider];
153→
154→    if (!keyName) {
155→      return NextResponse.json(
156→        { success: false, error: `Unsupported provider: ${agent.provider}` },
157→        { status: 400 }
158→      );
159→    }
160→
161→    // Get user's API key for this provider
162→    const userApiKey = await prisma.userApiKey.findUnique({
163→      where: {
164→        userId_keyName: {
165→          userId: agent.userId,
166→          keyName,
167→        },
168→      },
169→    });
170→
171→    if (!userApiKey) {
172→      return NextResponse.json(
173→        {
174→          success: false,
175→          error: `No API key configured for ${agent.provider}. Please add your API key in settings.`,
176→        },
177→        { status: 400 }
178→      );
179→    }
180→
181→    // Decrypt the API key
182→    const apiKey = decryptApiKey(userApiKey.encryptedKey, userApiKey.keyIv);
183→
184→    // Get or create conversation
185→    let conversation = await prisma.conversation.findUnique({
186→      where: {
187→        agentId_slug: {
188→          agentId: agent.id,
189→          slug: conversationId,
190→        },
191→      },
192→    });
193→
194→    if (!conversation) {
195→      conversation = await prisma.conversation.create({
196→        data: {
197→          agentId: agent.id,
198→          slug: conversationId,
199→          title: parsed.data.message.slice(0, 100),
200→        },
201→      });
202→
203→      // Log activity for new conversation (fire-and-forget)
204→      if (agent.userId) {
205→        logActivity({
206→          userId: agent.userId,
207→          type: 'AGENT_CONVERSATION_STARTED',
208→          targetName: agent.name,
209→          targetType: 'agent',
210→          agentId: agent.id,
211→        });
212→      }
213→    }
214→
215→    // Fetch recent messages for context
216→    const recentMessages = await prisma.message.findMany({
217→      where: { conversationId: conversation.id },
218→      orderBy: { createdAt: 'desc' },
219→      take: agent.maxMessagesInContext,
220→    });
221→
222→    // Reverse to get chronological order
223→    recentMessages.reverse();
224→
225→    // Save user message
226→    await prisma.message.create({
227→      data: {
228→        conversationId: conversation.id,
229→        role: 'USER',
230→        content: parsed.data.message,
231→      },
232→    });
233→
234→    // Build AI SDK messages from conversation history
235→    const { streamText, stepCountIs } = await import('ai');
236→
237→    const messages: ModelMessage[] = [];
238→
239→    // Add system prompt if defined
240→    if (agent.systemPrompt) {
241→      messages.push({
242→        role: 'system',
243→        content: agent.systemPrompt,
244→      });
245→    }
246→
247→    // Build a set of tool call IDs that have corresponding tool results
248→    // This is needed because AI SDK requires every tool call to have a matching tool result
249→    const toolResultIds = new Set(
250→      recentMessages.filter((m) => m.role === 'TOOL' && m.toolCallId).map((m) => m.toolCallId)
251→    );
252→
253→    // Add conversation history - properly format for AI SDK
254→    for (const msg of recentMessages) {
255→      if (msg.role === 'USER') {
256→        messages.push({ role: 'user', content: msg.content });
257→      } else if (msg.role === 'ASSISTANT') {
258→        // For assistant messages with tool calls, include ToolCallParts in content
259→        if (msg.toolCalls && Array.isArray(msg.toolCalls) && msg.toolCalls.length > 0) {
260→          // Only include tool calls that have matching tool results
261→          // AI SDK fails if there's a tool call without a corresponding tool result
262→          const validToolCalls = (
263→            msg.toolCalls as Array<{ toolCallId: string; toolName: string; args: unknown }>
264→          ).filter((tc) => toolResultIds.has(tc.toolCallId));
265→
266→          if (validToolCalls.length > 0) {
267→            const toolCallParts = validToolCalls.map((tc) => ({
268→              type: 'tool-call' as const,
269→              toolCallId: tc.toolCallId,
270→              toolName: tc.toolName,
271→              input: tc.args,
272→            }));
273→            // Content includes text (if any) plus tool call parts
274→            const content: Array<
275→              | { type: 'text'; text: string }
276→              | { type: 'tool-call'; toolCallId: string; toolName: string; input: unknown }
277→            > = [];
278→            if (msg.content) {
279→              content.push({ type: 'text', text: msg.content });
280→            }
281→            content.push(...toolCallParts);
282→            messages.push({
283→              role: 'assistant',
284→              content,
285→            });
286→          } else {
287→            // All tool calls are missing results, just include text content
288→            messages.push({
289→              role: 'assistant',
290→              content: msg.content || '',
291→            });
292→          }
293→        } else {
294→          messages.push({
295→            role: 'assistant',
296→            content: msg.content,
297→          });
298→        }
299→      } else if (msg.role === 'TOOL') {
300→        // Tool results use the 'tool' role with content array
301→        messages.push({
302→          role: 'tool',
303→          content: [
304→            {
305→              type: 'tool-result' as const,
306→              toolCallId: msg.toolCallId || '',
307→              toolName: msg.toolName || '',
308→              output: {
309→                type: 'json' as const,
310→                value: msg.toolResult,
311→              },
312→            },
313→          ],
314→        });
315→      }
316→    }
317→
318→    // Add new user message
319→    messages.push({ role: 'user', content: parsed.data.message });
320→
321→    // Build tools from agent configuration
322→    const tools = buildAgentTools(agent);
323→
324→    // Get the provider model
325→    const model = await getProviderModel(agent.provider, agent.modelId, apiKey);
326→
327→    // Create SSE stream
328→    const stream = new ReadableStream({
329→      // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex streaming logic
330→      async start(controller) {
331→        const encoder = new TextEncoder();
332→
333→        const sendEvent = (event: string, data: unknown) => {
334→          const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
335→          controller.enqueue(encoder.encode(message));
336→        };
337→
338→        try {
339→          const startTime = Date.now();
340→          let fullContent = '';
341→          // Accumulate tool calls with their input args
342→          const toolCallsMap: Map<string, { toolCallId: string; toolName: string; args: unknown }> =
343→            new Map();
344→          // Collect tool results to save AFTER assistant message (for correct chronological order)
345→          const pendingToolResults: Array<{
346→            toolCallId: string;
347→            toolName: string;
348→            output: unknown;
349→          }> = [];
350→          let inputTokens = 0;
351→          let outputTokens = 0;
352→
353→          // Stream the response with agentic loop control
354→          const result = await streamText({
355→            model,
356→            messages,
357→            tools,
358→            stopWhen: stepCountIs(agent.maxToolCallsPerTurn),
359→            onChunk: async ({ chunk }) => {
360→              // Stream tool calls as they come in and capture their inputs
361→              if (chunk.type === 'tool-call') {
362→                const input = 'args' in chunk ? chunk.args : chunk.input;
363→
364→                // Log tool call for debugging
365→                console.log('[Agent] Tool call initiated:', {
366→                  toolName: chunk.toolName,
367→                  toolCallId: chunk.toolCallId,
368→                  input: JSON.stringify(input).slice(0, 500),
369→                });
370→
371→                // Store tool call with input for later persistence
372→                toolCallsMap.set(chunk.toolCallId, {
373→                  toolCallId: chunk.toolCallId,
374→                  toolName: chunk.toolName,
375→                  args: input,
376→                });
377→                sendEvent('tool_call', {
378→                  toolCallId: chunk.toolCallId,
379→                  toolName: chunk.toolName,
380→                  input,
381→                });
382→              }
383→            },
384→            // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex callback
385→            onStepFinish: async ({ toolCalls, toolResults, usage }) => {
386→              // Capture tool calls from step finish (backup in case onChunk missed any)
387→              if (toolCalls && Array.isArray(toolCalls)) {
388→                for (const tc of toolCalls) {
389→                  if (!toolCallsMap.has(tc.toolCallId)) {
390→                    // Use 'input' from DynamicToolCall or fall back to type assertion for typed calls
391→                    const args =
392→                      'input' in tc ? tc.input : 'args' in tc ? (tc as { args: unknown }).args : {};
393→                    toolCallsMap.set(tc.toolCallId, {
394→                      toolCallId: tc.toolCallId,
395→                      toolName: tc.toolName,
396→                      args,
397→                    });
398→                  }
399→                }
400→              }
401→
402→              // Send tool results via SSE but don't save yet (save after assistant message for correct order)
403→              if (toolResults && toolResults.length > 0) {
404→                for (const tr of toolResults) {
405→                  // Check if this is an error result (AI SDK wraps errors in the output)
406→                  const isError =
407→                    tr.output && typeof tr.output === 'object' && 'error' in tr.output;
408→
409→                  // Log tool results for debugging
410→                  if (isError) {
411→                    console.error('[Agent] Tool execution failed:', {
412→                      toolName: tr.toolName,
413→                      toolCallId: tr.toolCallId,
414→                      error: tr.output,
415→                    });
416→                  } else {
417→                    console.log('[Agent] Tool execution success:', {
418→                      toolName: tr.toolName,
419→                      toolCallId: tr.toolCallId,
420→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
421→                    });
422→                  }
423→
424→                  sendEvent('tool_result', {
425→                    toolCallId: tr.toolCallId,
426→                    output: tr.output,
427→                    isError,
428→                  });
429→
430→                  // Collect tool results to save after assistant message
431→                  pendingToolResults.push({
432→                    toolCallId: tr.toolCallId,
433→                    toolName: tr.toolName,
434→                    output: tr.output,
435→                  });
436→
437→                  // Track each tool call execution event
438→                  trackExecution({
439→                    eventType: 'tool_call',
440→                    source: 'agent_chat',
441→                    userId: authResult.userId ?? undefined,
442→                    apiKeyId: authResult.apiKeyId ?? undefined,
443→                    agentId: agent.id,
444→                    toolName: tr.toolName,
445→                    status: isError ? 'error' : 'success',
446→                  });
447→                }
448→              }
449→
450→              // Track token usage
451→              if (usage) {
452→                inputTokens += usage.inputTokens ?? 0;
453→                outputTokens += usage.outputTokens ?? 0;
454→              }
455→            },
456→          });
457→
458→          // Stream text chunks
459→          for await (const chunk of result.textStream) {
460→            fullContent += chunk;
461→            sendEvent('chunk', { type: 'text', text: chunk });
462→          }
463→
464→          // Get final response data
465→          const finalUsage = await result.usage;
466→
467→          // Convert tool calls map to array for storage
468→          const allToolCalls = Array.from(toolCallsMap.values());
469→
470→          // Update token counts from final usage
471→          if (finalUsage) {
472→            inputTokens = finalUsage.inputTokens ?? inputTokens;
473→            outputTokens = finalUsage.outputTokens ?? outputTokens;
474→          }
475→
476→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
477→          const assistantMessage = await prisma.message.create({
478→            data: {
479→              conversationId: conversation.id,
480→              role: 'ASSISTANT',
481→              content: fullContent,
482→              // Cast to Prisma-compatible JSON type
483→              toolCalls:
484→                allToolCalls.length > 0
485→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
486→                  : Prisma.JsonNull,
487→              inputTokens,
488→              outputTokens,
489→            },
490→          });
491→
492→          // Now save TOOL messages (after assistant, for correct chronological order)
493→          for (const tr of pendingToolResults) {
494→            await prisma.message.create({
495→              data: {
496→                conversationId: conversation.id,
497→                role: 'TOOL',
498→                content: JSON.stringify(tr.output),
499→                toolCallId: tr.toolCallId,
500→                toolName: tr.toolName,
501→                toolResult: tr.output as object,
502→              },
503→            });
504→          }
505→
506→          // Update conversation timestamp
507→          await prisma.conversation.update({
508→            where: { id: conversation.id },
509→            data: { updatedAt: new Date() },
510→          });
511→
512→          const executionTimeMs = Date.now() - startTime;
513→
514→          // Send token usage
515→          sendEvent('tokens', {
516→            inputTokens,
517→            outputTokens,
518→            totalTokens: inputTokens + outputTokens,
519→          });
520→
521→          // Send completion event
522→          sendEvent('complete', {
523→            messageId: assistantMessage.id,
524→            conversationId: conversation.id,
525→            executionTimeMs,
526→          });
527→
528→          // Track agent run execution event
529→          trackExecution({
530→            eventType: 'agent_run',
531→            source: 'agent_chat',
532→            userId: authResult.userId ?? undefined,
533→            apiKeyId: authResult.apiKeyId ?? undefined,
534→            agentId: agent.id,
535→            status: 'success',
536→            durationMs: executionTimeMs,
537→            tokensIn: inputTokens,
538→            tokensOut: outputTokens,
539→          });
540→
541→          // Track usage
542→          if (authResult.userId) {
543→            trackUsage({
544→              apiKeyId: authResult.apiKeyId ?? undefined,
545→              userId: authResult.userId,
546→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
547→              method: 'POST',
548→              statusCode: 200,
549→              latencyMs: executionTimeMs,
550→              resourceType: 'agent',
551→              resourceId: agent.id,
552→              tokensIn: inputTokens,
553→              tokensOut: outputTokens,
554→              model: agent.modelId,
555→            });
556→          }
557→        } catch (error) {
558→          // Log detailed error for debugging
559→          console.error('[Agent] Conversation stream error:', {
560→            error: error instanceof Error ? error.message : String(error),
561→            stack: error instanceof Error ? error.stack : undefined,
562→            agentId: agent.id,
563→            conversationId: conversation.id,
564→          });
565→          sendEvent('error', {
566→            message: error instanceof Error ? error.message : 'Unknown error',
567→          });
568→
569→          // Track agent run error
570→          trackExecution({
571→            eventType: 'agent_run',
572→            source: 'agent_chat',
573→            userId: authResult.userId ?? undefined,
574→            apiKeyId: authResult.apiKeyId ?? undefined,
575→            agentId: agent.id,
576→            status: 'error',
577→            durationMs: Date.now() - startTime,
578→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
579→          });
580→
581→          // Track error
582→          if (authResult.userId) {
583→            trackUsage({
584→              apiKeyId: authResult.apiKeyId ?? undefined,
585→              userId: authResult.userId,
586→              endpoint: `/api/${username}/agents/${agentSlug}/conversation/${conversationId}`,
587→              method: 'POST',
588→              statusCode: 500,
589→              latencyMs: Date.now() - startTime,
590→              resourceType: 'agent',
591→              resourceId: agent.id,
592→              errorCode: 'STREAM_ERROR',
593→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
594→            });
595→          }
596→        } finally {
597→          controller.close();
598→        }
599→      },
600→    });
601→
602→    return new NextResponse(stream, {
603→      headers: {
604→        'Content-Type': 'text/event-stream',
605→        'Cache-Control': 'no-cache',
606→        Connection: 'keep-alive',
607→      },
608→    });
609→  } catch (error) {
610→    console.error('Failed to process message:', error);
611→    return NextResponse.json(
612→      {
613→        success: false,
614→        error: error instanceof Error ? error.message : 'Failed to process message',
615→      },
616→      { status: 500 }
617→    );
618→  }
619→}
