  35→
  36→// Cache for imported tool modules with TTL
  37→const moduleCache = new Map<string, CacheEntry>();
  38→
  39→/**
  40→ * Get module from cache if not expired
  41→ */
  42→function getCachedModule(cacheKey: string): CacheEntry | null {
  43→  const entry = moduleCache.get(cacheKey);
  44→  if (!entry) return null;
  45→
  46→  if (Date.now() > entry.expiresAt) {
  47→    moduleCache.delete(cacheKey);
  48→    console.log(`🗑️  Cache expired: ${cacheKey}`);
  49→    return null;
  50→  }
  51→
  52→  return entry;
  53→}
  54→
  55→/**
  56→ * Store module in cache with TTL
  57→ */
  58→// biome-ignore lint/suspicious/noExplicitAny: Tool types are dynamic and vary by package
  59→function setCachedModule(cacheKey: string, module: any, isFactory: boolean): void {
  60→  // Evict oldest entries if cache is full
  61→  if (moduleCache.size >= MAX_CACHE_SIZE) {
  62→    const entriesToEvict = Math.max(1, Math.floor(MAX_CACHE_SIZE * 0.2)); // Evict 20%
  63→    const keys = Array.from(moduleCache.keys());
  64→    for (let i = 0; i < entriesToEvict && i < keys.length; i++) {
  65→      moduleCache.delete(keys[i]);
  66→    }
  67→    console.log(`🗑️  Evicted ${entriesToEvict} cache entries (cache was full at ${MAX_CACHE_SIZE})`);
  68→  }
  69→
  70→  moduleCache.set(cacheKey, {
  71→    module,
  72→    expiresAt: Date.now() + CACHE_TTL_MS,
  73→    isFactory,
  74→  });
  75→  console.log(`📦 Cached (TTL ${CACHE_TTL_MS / 1000}s): ${cacheKey}`);
  76→}
  77→
  78→/**
  79→ * Cleanup expired cache entries
  80→ */
  81→function cleanupExpiredCache(): void {
  82→  const now = Date.now();
  83→  let cleaned = 0;
  84→  for (const [key, entry] of moduleCache.entries()) {
  85→    if (now > entry.expiresAt) {
  86→      moduleCache.delete(key);
  87→      cleaned++;
  88→    }
  89→  }
  90→  if (cleaned > 0) {
  91→    console.log(`🗑️  Cleaned ${cleaned} expired cache entries`);
  92→  }
  93→}
  94→
  95→// Run cache cleanup every minute
  96→setInterval(cleanupExpiredCache, 60 * 1000);
