 175→/**
 176→ * Sanitize JSON Schema to fix common issues
 177→ * - Replaces invalid type "None" with "object"
 178→ * - Ensures type is always set
 179→ * - Ensures object schemas have properties
 180→ */
 181→// biome-ignore lint/suspicious/noExplicitAny: JSON Schema can have any structure
 182→function sanitizeJsonSchema(schema: any): any {
 183→  if (!schema || typeof schema !== 'object') {
 184→    console.warn('⚠️  Invalid schema (not an object), returning default object schema');
 185→    return { type: 'object', properties: {}, additionalProperties: false };
 186→  }
 187→
 188→  // Clone the schema to avoid mutating the original
 189→  const sanitized = { ...schema };
 190→
 191→  // Fix invalid type "None" (common in Python-based tools)
 192→  if (sanitized.type === 'None' || sanitized.type === 'none' || sanitized.type === null) {
 193→    console.warn(`⚠️  Invalid schema type "${sanitized.type}", replacing with "object"`);
 194→    sanitized.type = 'object';
 195→    if (!sanitized.properties) {
 196→      sanitized.properties = {};
 197→    }
 198→    if (sanitized.additionalProperties === undefined) {
 199→      sanitized.additionalProperties = false;
 200→    }
 201→  }
 202→
 203→  // Ensure type is set
 204→  if (!sanitized.type) {
 205→    console.warn('⚠️  Schema missing type, defaulting to "object"');
 206→    sanitized.type = 'object';
 207→    if (!sanitized.properties) {
 208→      sanitized.properties = {};
 209→    }
 210→    if (sanitized.additionalProperties === undefined) {
 211→      sanitized.additionalProperties = false;
 212→    }
 213→  }
 214→
 215→  // Recursively sanitize nested schemas
 216→  if (sanitized.properties && typeof sanitized.properties === 'object') {
 217→    for (const [key, value] of Object.entries(sanitized.properties)) {
 218→      if (value && typeof value === 'object') {
 219→        sanitized.properties[key] = sanitizeJsonSchema(value);
 220→      }
 221→    }
 222→  }
 223→
 224→  // Sanitize array items
 225→  if (sanitized.items && typeof sanitized.items === 'object') {
 226→    sanitized.items = sanitizeJsonSchema(sanitized.items);
 227→  }
 228→
 229→  // Sanitize anyOf/oneOf/allOf
 230→  for (const key of ['anyOf', 'oneOf', 'allOf']) {
 231→    if (Array.isArray(sanitized[key])) {
 232→      // biome-ignore lint/suspicious/noExplicitAny: JSON Schema types are dynamic
 233→      sanitized[key] = sanitized[key].map((s: any) => sanitizeJsonSchema(s));
 234→    }
 235→  }
 236→
 237→  return sanitized;
 238→}
