 313→
 314→          // Variation 2: Normalized to camelCase apiKey (e.g., { apiKey: 'xxx' })
 315→          const apiKeyValue = Object.entries(env).find(([key]) =>
 316→            key.toUpperCase().includes('API_KEY')
 317→          )?.[1];
 318→          if (apiKeyValue) {
 319→            configVariations.push({ apiKey: apiKeyValue });
 320→          }
 321→
 322→          // Variation 3: Normalized to key (e.g., { key: 'xxx' })
 323→          if (apiKeyValue) {
 324→            configVariations.push({ key: apiKeyValue });
 325→          }
 326→
 327→          // Try each config variation
 328→          for (const config of configVariations) {
 329→            try {
 330→              console.log(`  Trying: ${name}(`, Object.keys(config), ')');
 331→              factoryResult = rawExport(config);
