 778→/**
 779→ * List all exports from a package and identify which are valid AI SDK tools
 780→ */
 781→async function listExports(req: Request): Promise<Response> {
 782→  try {
 783→    const body = await req.json();
 784→    const { packageName, version, importUrl, env } = body;
 785→
 786→    if (!packageName || !version) {
 787→      return Response.json(
 788→        {
 789→          success: false,
 790→          error: 'Missing required fields: packageName, version',
 791→        },
 792→        { status: 400 }
 793→      );
 794→    }
 795→
 796→    // Dynamic import from esm.sh
 797→    const url = importUrl || `https://esm.sh/${packageName}@${version}`;
 798→    console.log(`📦 Listing exports from: ${url}`);
 799→
 800→    const module = await import(url);
 801→    const allExports = Object.keys(module);
 802→
 803→    // Filter out 'default' and identify which exports are valid tools
 804→    const tools: Array<{
 805→      name: string;
 806→      isValidTool: boolean;
 807→      description?: string;
 808→      error?: string;
 809→    }> = [];
 810→
 811→    for (const exportKey of allExports) {
 812→      if (exportKey === 'default') continue;
 813→
 814→      let rawExport = module[exportKey];
 815→
 816→      // Check if it's a factory function
 817→      if (typeof rawExport === 'function' && !rawExport.description && !rawExport.execute) {
 818→        // Try to call factory with no args
 819→        try {
 820→          const factoryResult = rawExport();
 821→          if (factoryResult?.description && factoryResult?.execute) {
 822→            rawExport = factoryResult;
 823→          } else if (env && typeof env === 'object') {
 824→            // Try with env config
 825→            const configResult = rawExport({ ...env });
 826→            if (configResult?.description && configResult?.execute) {
 827→              rawExport = configResult;
 828→            }
 829→          }
 830→        } catch {
 831→          // Factory call failed, continue checking
 832→        }
 833→      }
 834→
 835→      // Check if it's a valid AI SDK tool
 836→      if (rawExport?.description && rawExport?.execute) {
 837→        tools.push({
 838→          name: exportKey,
 839→          isValidTool: true,
 840→          description: rawExport.description,
 841→        });
 842→      } else if (typeof rawExport === 'object' && rawExport !== null) {
 843→        // It's an object but not a valid tool - might be a factory that needs specific config
 844→        tools.push({
 845→          name: exportKey,
 846→          isValidTool: false,
 847→          error: 'Not a valid AI SDK tool (missing description or execute)',
 848→        });
 849→      }
