 874→// Track startup time for uptime reporting
 875→const startedAt = Date.now();
 876→
 877→/**
 878→ * Health check
 879→ */
 880→function health(): Response {
 881→  return Response.json({
 882→    status: 'ok',
 883→    timestamp: new Date().toISOString(),
 884→    uptimeSeconds: Math.floor((Date.now() - startedAt) / 1000),
 885→    cacheSize: moduleCache.size,
 886→    maxCacheSize: MAX_CACHE_SIZE,
 887→    denoVersion: Deno.version.deno,
 888→    v8Version: Deno.version.v8,
 889→    httpImports: true,
 890→  });
 891→}
 892→
 893→/**
 894→ * Cache stats
 895→ */
 896→function cacheStats(): Response {
 897→  const now = Date.now();
 898→  const entries = Array.from(moduleCache.entries()).map(([key, entry]) => ({
 899→    key,
 900→    isFactory: entry.isFactory,
 901→    expiresIn: Math.max(0, Math.round((entry.expiresAt - now) / 1000)),
 902→  }));
 903→
 904→  return Response.json({
 905→    success: true,
 906→    cacheSize: moduleCache.size,
 907→    ttlSeconds: CACHE_TTL_MS / 1000,
 908→    cachedTools: entries,
 909→  });
 910→}
 911→
 912→/**
 913→ * Clear cache
 914→ */
 915→function clearCache(): Response {
 916→  const size = moduleCache.size;
 917→  moduleCache.clear();
 918→  console.log(`🗑️  Cleared cache (${size} entries)`);
 919→
 920→  return Response.json({
 921→    success: true,
 922→    message: `Cleared ${size} cached modules`,
 923→  });
 924→}
